package com.yourapp.drama.workflow;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.yourapp.drama.persistence.DocumentStore;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.*;

import static com.yourapp.drama.persistence.ResourceKind.*;
import static com.yourapp.drama.workflow.Documents.*;

@Service
public class NovelAnalysisService {
    private static final Set<String> PROFILES=Set.of("FAST","STANDARD","DEEP");
    private static final List<String> REQUIRED_ARRAYS=List.of("characterMentions","locationMentions","propMentions","events","storyFacts","relationshipChanges","knowledgeChanges","timelineHints","conflicts","foreshadowing","payoffs","importantDialogue");
    private final DocumentStore store;private final NovelAnalysisProvider provider;private final NovelEntityResolutionService entities;private final NovelAnalysisEstimateService estimates;
    public NovelAnalysisService(DocumentStore store,NovelAnalysisProvider provider,NovelEntityResolutionService entities,NovelAnalysisEstimateService estimates){this.store=store;this.provider=provider;this.entities=entities;this.estimates=estimates;}
    public ObjectNode estimate(String novelId){return estimates.estimate(novelId);}
    public ObjectNode start(String novelId,ObjectNode request){if(!request.path("confirmed").asBoolean(false))throw new WorkflowException("ANALYSIS_CONFIRMATION_REQUIRED","小说分析必须由用户明确开始");return run(novelId,request,false);}
    public ObjectNode resume(String novelId,ObjectNode request){return run(novelId,request,true);}
    private ObjectNode run(String novelId,ObjectNode request,boolean resume){ObjectNode source=store.get(NOVEL_SOURCE,novelId);if(!Set.of("READY","ANALYZED").contains(text(source,"status")))throw new WorkflowException("NOVEL_NOT_READY","小说尚未完成解析");String profile=request.path("profile").asText("STANDARD").toUpperCase(Locale.ROOT);if(!PROFILES.contains(profile))throw new IllegalArgumentException("分析档位只支持 FAST、STANDARD、DEEP");Set<String> injectedFailures=new HashSet<>();request.path("failChunkIds").forEach(node->injectedFailures.add(node.asText()));List<ObjectNode> chunks=activeChunks(source);for(ObjectNode chunk:chunks){ObjectNode latest=latestJob(project(source),id(chunk));boolean same=latest!=null&&profile.equals(text(latest,"profile"))&&text(chunk,"contentHash").equals(text(latest,"contentHash"));if(same&&"SUCCEEDED".equals(text(latest,"status")))continue;if(same&&"FAILED".equals(text(latest,"status"))&&!resume)continue;if(resume&&same&&!"FAILED".equals(text(latest,"status")))continue;analyzeChunk(source,chunk,profile,injectedFailures.contains(id(chunk)));}ObjectNode state=progress(novelId);if(state.path("failedChunks").asInt()==0&&state.path("pendingChunks").asInt()==0)aggregate(source,profile);state=progress(novelId);state.put("status",state.path("failedChunks").asInt()>0?"PARTIAL_FAILED":state.path("pendingChunks").asInt()>0?"RUNNING":"SUCCEEDED");return state;}
    private void analyzeChunk(ObjectNode source,ObjectNode chunk,String profile,boolean fail){ObjectNode chapter=store.get(NOVEL_CHAPTER,required(chunk,"chapterId"));int version=store.list(NOVEL_ANALYSIS_JOB,project(source),null).stream().filter(job->id(chunk).equals(text(job,"chunkId"))).mapToInt(job->job.path("analysisVersion").asInt()).max().orElse(0)+1;String key="novel:"+id(source)+":chapter:"+chapter.path("chapterNo").asInt()+":chunk:"+chunk.path("chunkNo").asInt()+":analysis:"+version;ObjectNode job=store.create(NOVEL_ANALYSIS_JOB,obj().put("projectId",project(source)).put("novelId",id(source)).put("chapterId",id(chapter)).put("chunkId",id(chunk)).put("status","PENDING").put("idempotencyKey",key).put("contentHash",text(chunk,"contentHash")).put("profile",profile).put("analysisVersion",version).put("attempt",1));job=store.update(NOVEL_ANALYSIS_JOB,id(job),revision(job),job.deepCopy().put("status","RUNNING").put("startedAt",Instant.now().toString()));if(fail){store.update(NOVEL_ANALYSIS_JOB,id(job),revision(job),job.deepCopy().put("status","FAILED").put("failureCode","INJECTED_CHUNK_FAILURE").put("finishedAt",Instant.now().toString()));return;}ObjectNode request=obj().put("sourceBoundary","UNTRUSTED_NOVEL_TEXT").put("sourceText",text(chunk,"normalizedText")).put("novelId",id(source)).put("chapterId",id(chapter)).put("chunkId",id(chunk)).put("profile",profile).put("contentHash",text(chunk,"contentHash"));ObjectNode output=provider.analyze(request);validate(output);ObjectNode document=output.deepCopy().put("projectId",project(source)).put("novelId",id(source)).put("chapterId",id(chapter)).put("chunkId",id(chunk)).put("contentHash",text(chunk,"contentHash")).put("analysisVersion",version).put("profile",profile).put("sourceBoundary","UNTRUSTED_NOVEL_TEXT").put("requestInputChars",text(chunk,"normalizedText").length()).put("requestSchemaVersion",1);document.putArray("sourceRefs").add(id(chunk));ObjectNode saved=store.create(NOVEL_CHUNK_ANALYSIS,document);materialize(source,chunk,chapter,saved);ObjectNode running=store.get(NOVEL_ANALYSIS_JOB,id(job));store.update(NOVEL_ANALYSIS_JOB,id(job),revision(running),running.deepCopy().put("status","SUCCEEDED").put("analysisId",id(saved)).put("finishedAt",Instant.now().toString()));}
    private void validate(ObjectNode output){if(text(output,"summary").isBlank())throw new WorkflowException("ANALYSIS_SCHEMA_INVALID","ChunkAnalysis.summary 缺失");for(String field:REQUIRED_ARRAYS)if(!output.path(field).isArray())throw new WorkflowException("ANALYSIS_SCHEMA_INVALID","ChunkAnalysis."+field+" 必须为数组");if(output.has("wholeNovelText"))throw new WorkflowException("WHOLE_NOVEL_PROMPT_FORBIDDEN","分析响应不能携带整本小说");}
    private void materialize(ObjectNode source,ObjectNode chunk,ObjectNode chapter,ObjectNode analysis){Map<String,String> characters=new LinkedHashMap<>();for(JsonNode name:analysis.path("characterMentions")){ObjectNode resolved=entities.resolve(project(source),id(source),"CHARACTER",name.asText(),List.of(),.95,List.of(id(chunk)));characters.put(name.asText(),text(resolved,"canonicalEntityId"));}for(JsonNode name:analysis.path("locationMentions"))entities.resolve(project(source),id(source),"LOCATION",name.asText(),List.of(),.95,List.of(id(chunk)));for(JsonNode name:analysis.path("propMentions"))entities.resolve(project(source),id(source),"PROP",name.asText(),List.of(),.95,List.of(id(chunk)));List<ObjectNode> facts=new ArrayList<>();int factNo=0;for(JsonNode statement:analysis.path("storyFacts")){String key="novel:"+id(source)+":chunk:"+id(chunk)+":analysis:"+analysis.path("analysisVersion").asInt()+":fact:"+(++factNo);ObjectNode fact=obj().put("projectId",project(source)).put("novelId",id(source)).put("factKey",key).put("statement",statement.asText()).put("predicate","SOURCE_ASSERTION").put("validFromStoryTime",chapter.path("chapterNo").asDouble()).put("status","ACTIVE").put("source","NOVEL");fact.putArray("sourceRefs").add(id(chunk));facts.add(store.create(STORY_FACT,fact));}for(JsonNode change:analysis.path("knowledgeChanges")){String characterId=characters.get(text(change,"character"));ObjectNode fact=facts.stream().filter(item->text(item,"statement").contains(text(change,"fact"))).findFirst().orElse(facts.isEmpty()?null:facts.getFirst());if(characterId!=null&&fact!=null){ObjectNode knowledge=obj().put("projectId",project(source)).put("novelId",id(source)).put("characterId",characterId).put("factId",id(fact)).put("knowledgeState",change.path("state").asText("KNOWN")).put("knownFromStoryTime",chapter.path("chapterNo").asDouble()).put("source","NOVEL");knowledge.putArray("sourceRefs").add(id(chunk));store.create(CHARACTER_KNOWLEDGE,knowledge);}}for(JsonNode change:analysis.path("relationshipChanges")){String subject=characters.get(text(change,"subject")),object=characters.get(text(change,"object"));if(subject!=null&&object!=null){ObjectNode relation=obj().put("projectId",project(source)).put("novelId",id(source)).put("subjectCharacterId",subject).put("objectCharacterId",object).put("relationshipType",change.path("type").asText("RELATED")).put("state",change.path("type").asText("RELATED")).put("validFromStoryTime",chapter.path("chapterNo").asDouble()).put("source","NOVEL");relation.putArray("sourceRefs").add(id(chunk));store.create(RELATIONSHIP,relation);}}}
    private void aggregate(ObjectNode source,String profile){ObjectNode current=store.get(NOVEL_SOURCE,id(source));int analysisRevision=current.path("analysisRevision").asInt(0)+1;List<ObjectNode> chapters=store.list(NOVEL_CHAPTER,project(source),id(source)).stream().filter(c->c.path("active").asBoolean(true)).sorted(Comparator.comparingDouble(c->c.path("displayOrder").asDouble(c.path("chapterNo").asDouble()))).toList();List<ObjectNode> chapterAnalyses=new ArrayList<>();for(ObjectNode chapter:chapters){List<ObjectNode> analyses=store.list(NOVEL_CHUNK,project(source),id(chapter)).stream().filter(c->c.path("active").asBoolean(true)).map(c->currentAnalysis(project(source),c,profile)).filter(Objects::nonNull).toList();ObjectNode aggregate=obj().put("projectId",project(source)).put("novelId",id(source)).put("chapterId",id(chapter)).put("analysisRevision",analysisRevision).put("profile",profile).put("chapterSummary",join(analyses,"summary")).put("openingState",analyses.isEmpty()?"":text(analyses.getFirst(),"summary")).put("endingState",analyses.isEmpty()?"":text(analyses.getLast(),"summary")).put("plotImportance",Math.min(100,40+analyses.size()*10));for(String field:List.of("characters","locations","props","newFacts","resolvedFacts","relationshipChanges","knowledgeChanges","turningPoints"))aggregate.putArray(field);copyDistinct(analyses,"characterMentions",aggregate.withArray("characters"));copyDistinct(analyses,"locationMentions",aggregate.withArray("locations"));copyDistinct(analyses,"propMentions",aggregate.withArray("props"));copyDistinct(analyses,"storyFacts",aggregate.withArray("newFacts"));copyDistinct(analyses,"relationshipChanges",aggregate.withArray("relationshipChanges"));copyDistinct(analyses,"knowledgeChanges",aggregate.withArray("knowledgeChanges"));copyDistinct(analyses,"events",aggregate.withArray("turningPoints"));aggregate.putArray("sourceRefs");analyses.forEach(a->aggregate.withArray("sourceRefs").add(id(a)));chapterAnalyses.add(store.create(NOVEL_CHAPTER_ANALYSIS,aggregate));}List<ObjectNode> arcs=new ArrayList<>();for(int from=0;from<chapters.size();from+=10){int to=Math.min(chapters.size(),from+10);ObjectNode arc=obj().put("projectId",project(source)).put("novelId",id(source)).put("startChapter",chapters.get(from).path("chapterNo").asInt()).put("endChapter",chapters.get(to-1).path("chapterNo").asInt()).put("analysisRevision",analysisRevision).put("arcGoal","推进章节 "+(from+1)+" 至 "+to).put("mainConflict",join(chapterAnalyses.subList(from,to),"chapterSummary")).put("climax",text(chapterAnalyses.get(to-1),"endingState")).put("resolution","待后续章节验证");for(String field:List.of("turningPoints","characterArcs","factsIntroduced","factsResolved","foreshadowing","payoffs"))arc.putArray(field);chapterAnalyses.subList(from,to).forEach(a->arc.withArray("turningPoints").addAll((ArrayNode)a.path("turningPoints")));arcs.add(store.create(NOVEL_STORY_ARC,arc));}ObjectNode graph=obj().put("projectId",project(source)).put("novelId",id(source)).put("analysisRevision",analysisRevision).put("profile",profile).put("mainPlot",join(chapterAnalyses,"chapterSummary"));for(String field:List.of("canonicalCharacters","canonicalLocations","canonicalProps","subPlots","storyFacts","relationships","characterKnowledge","timelineEvents","worldRules","storyArcs","foreshadowing","payoffs","characterArcs"))graph.putArray(field);store.list(CHARACTER,project(source),null).stream().filter(e->id(source).equals(text(e,"novelId"))).forEach(e->graph.withArray("canonicalCharacters").add(id(e)));store.list(LOCATION,project(source),null).stream().filter(e->id(source).equals(text(e,"novelId"))).forEach(e->graph.withArray("canonicalLocations").add(id(e)));store.list(PROP,project(source),null).stream().filter(e->id(source).equals(text(e,"novelId"))).forEach(e->graph.withArray("canonicalProps").add(id(e)));store.list(STORY_FACT,project(source),null).stream().filter(e->id(source).equals(text(e,"novelId"))).forEach(e->graph.withArray("storyFacts").add(id(e)));store.list(RELATIONSHIP,project(source),null).stream().filter(e->id(source).equals(text(e,"novelId"))).forEach(e->graph.withArray("relationships").add(id(e)));store.list(CHARACTER_KNOWLEDGE,project(source),null).stream().filter(e->id(source).equals(text(e,"novelId"))).forEach(e->graph.withArray("characterKnowledge").add(id(e)));arcs.forEach(arc->graph.withArray("storyArcs").add(id(arc)));store.create(NOVEL_STORY_GRAPH,graph);current=store.get(NOVEL_SOURCE,id(source));store.update(NOVEL_SOURCE,id(source),revision(current),current.deepCopy().put("analysisRevision",analysisRevision).put("analysisProfile",profile).put("analysisStatus","SUCCEEDED"));}
    public ObjectNode progress(String novelId){ObjectNode source=store.get(NOVEL_SOURCE,novelId);List<ObjectNode> chunks=activeChunks(source);int succeeded=0,failed=0;for(ObjectNode chunk:chunks){ObjectNode job=latestJob(project(source),id(chunk));if(job!=null&&text(chunk,"contentHash").equals(text(job,"contentHash"))){if("SUCCEEDED".equals(text(job,"status")))succeeded++;else if("FAILED".equals(text(job,"status")))failed++;}}int chapterDone=(int)store.list(NOVEL_CHAPTER_ANALYSIS,project(source),null).stream().filter(a->novelId.equals(text(a,"novelId"))&&a.path("analysisRevision").asInt()==source.path("analysisRevision").asInt()).count();int arcs=(int)store.list(NOVEL_STORY_ARC,project(source),novelId).stream().filter(a->a.path("analysisRevision").asInt()==source.path("analysisRevision").asInt()).count();return obj().put("novelId",novelId).put("parsedChapters",source.path("chapterCount").asInt()).put("totalChapters",source.path("chapterCount").asInt()).put("semanticChunks",chunks.size()).put("totalChunks",chunks.size()).put("succeededChunks",succeeded).put("failedChunks",failed).put("pendingChunks",chunks.size()-succeeded-failed).put("chapterSummaries",chapterDone).put("storyArcs",arcs).put("globalGraph",store.list(NOVEL_STORY_GRAPH,project(source),novelId).isEmpty()?"NOT_STARTED":"SUCCEEDED");}
    private List<ObjectNode> activeChunks(ObjectNode source){Map<String,Integer> chapterNo=new HashMap<>();store.list(NOVEL_CHAPTER,project(source),id(source)).stream().filter(c->c.path("active").asBoolean(true)).forEach(c->chapterNo.put(id(c),c.path("chapterNo").asInt()));return store.list(NOVEL_CHUNK,project(source),null).stream().filter(c->id(source).equals(text(c,"novelId"))&&c.path("active").asBoolean(true)&&chapterNo.containsKey(text(c,"chapterId"))).sorted(Comparator.comparingInt((ObjectNode c)->chapterNo.get(text(c,"chapterId"))).thenComparingInt(c->c.path("chunkNo").asInt())).toList();}
    private ObjectNode latestJob(String projectId,String chunkId){return store.list(NOVEL_ANALYSIS_JOB,projectId,null).stream().filter(job->chunkId.equals(text(job,"chunkId"))).max(Comparator.comparingInt(job->job.path("analysisVersion").asInt())).orElse(null);}
    private ObjectNode currentAnalysis(String projectId,ObjectNode chunk,String profile){return store.list(NOVEL_CHUNK_ANALYSIS,projectId,id(chunk)).stream().filter(a->text(chunk,"contentHash").equals(text(a,"contentHash"))&&profile.equals(text(a,"profile"))).max(Comparator.comparingInt(a->a.path("analysisVersion").asInt())).orElse(null);}
    private static void copyDistinct(List<ObjectNode> sources,String field,ArrayNode target){Set<String> seen=new LinkedHashSet<>();for(ObjectNode source:sources)for(JsonNode value:source.path(field)){String key=value.toString();if(seen.add(key))target.add(value.deepCopy());}}
    private static String join(List<ObjectNode> sources,String field){return String.join(" ",sources.stream().map(value->text(value,field)).filter(value->!value.isBlank()).toList());}
}
